const event = $input.first().json.body;
if (event.pipeline !== 'open_revenue' || event.status !== 'success' || !(event.row_count > 0)) { throw new Error('Invalid quality event'); }
return [{ json: { received: true, pipeline: event.pipeline, row_count: event.row_count, sha256: event.sha256 } }];
